package com.company.platform.integration.api;import com.company.platform.integration.application.*;import com.company.platform.integration.framework.AdapterRegistry;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/integration") public class FrameworkController{private final SynchronizationEngine sync;private final IntegrationScheduler scheduler;private final AdapterRegistry adapters;public FrameworkController(SynchronizationEngine s,IntegrationScheduler x,AdapterRegistry a){sync=s;scheduler=x;adapters=a;}@PostMapping("/connectors/{id}/execute")public Map<String,Object> execute(@PathVariable UUID id){return scheduler.manual(id,"MANUAL");}@PostMapping("/connectors/{id}/sync")public Map<String,Object> synchronize(@PathVariable UUID id,@RequestBody(required=false)Map<String,Object> payload){return sync.synchronize(id,"ON_DEMAND",payload==null?Map.of():payload);}@PostMapping("/connectors/{id}/test")public Map<String,Object> test(@PathVariable UUID id){return scheduler.manual(id,"TEST");}@GetMapping("/scheduler")public Map<String,Object> scheduler(){return Map.of("enabled",true,"mode","configurable","providers",adapters.providers());}@PostMapping("/scheduler/run")public Map<String,Object> run(@RequestParam UUID connectorId){return scheduler.manual(connectorId,"SCHEDULED");}}
